import{_ as i,o as _,c as r,a2 as l}from"./chunks/framework.D3xAlClj.js";const p=JSON.parse('{"title":"如何在WINDOWS自带的防火墙中打开数据库服务器的端口","description":"","frontmatter":{"title":"如何在WINDOWS自带的防火墙中打开数据库服务器的端口","date":"2026-10-14T16:03:16.000Z","lastmod":"2026-11-24T18:58:17.000Z"},"headers":[],"relativePath":"guide/1115.md","filePath":"guide/帮助文档/安装卸载说明/网络版安装相关问题说明/如何在WINDOWS自带的防火墙中打开数据库服务器的端口.md"}'),t={name:"guide/1115.md"};function a(o,e,s,d,n,S){return _(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="如何在windows自带的防火墙中打开数据库服务器的端口" tabindex="-1">如何在WINDOWS自带的防火墙中打开数据库服务器的端口 <a class="header-anchor" href="#如何在windows自带的防火墙中打开数据库服务器的端口" aria-label="Permalink to &quot;如何在WINDOWS自带的防火墙中打开数据库服务器的端口&quot;">​</a></h1><p>‍</p><ol><li>单击“开始”和“控制面板”，再单击“网络和Internet连接”。</li><li>单击“Windows 防火墙设置”。</li><li>在“例外”选项卡上的“程序和服务”框中，您可能看到已列出 SQL Server，但是未将它选择为例外。如果您选中该复选框，则 Windows 将打开端口 1433 来放入 TCP 请求。</li><li>如未例出,可以通过添加SQL Server程序来打开端口，则请执行下列操作：</li><li>单击“添加程序”。</li><li>单击“浏览”。</li><li>导航到 drive:/Program Files/Microsoft SQL Server/MSSQL.1\\MSSQL\\BINN</li><li>将文件 sqlservr.exe 添加到例外列表中。</li><li>由于动态端口需要同时开启Sql browser服务,所以需要同时加入1434:upd端口，这是sql browser服务用来实现动态端口所必需的。</li></ol>',3)])])}const W=i(t,[["render",a]]);export{p as __pageData,W as default};
